/// Success exit code.
pub const FC_EXIT_CODE_OK: u8 = 0;
/// Generic error exit code.
pub const FC_EXIT_CODE_GENERIC_ERROR: u8 = 1;
/// Generic exit code for an error considered not possible to occur if the program logic is sound.
pub const FC_EXIT_CODE_UNEXPECTED_ERROR: u8 = 2;
/// Firecracker was shut down after intercepting a restricted system call.
pub const FC_EXIT_CODE_BAD_SYSCALL: u8 = 148;
/// Firecracker was shut down after intercepting `SIGBUS`.
pub const FC_EXIT_CODE_SIGBUS: u8 = 149;
/// Firecracker was shut down after intercepting `SIGSEGV`.
pub const FC_EXIT_CODE_SIGSEGV: u8 = 150;
/// Bad configuration for microvm's resources, when using a single json.
pub const FC_EXIT_CODE_BAD_CONFIGURATION: u8 = 152;
/// Command line arguments parsing error.
pub const FC_EXIT_CODE_ARG_PARSING: u8 = 153;

/// Errors associated with the VMM internal logic. These errors cannot be generated by direct user
/// input, but can result from bad configuration of the host (for example if Firecracker doesn't
/// have permissions to open the KVM fd).
#[derive(Debug)]
pub enum Error {
    /// This error is thrown by the minimal boot loader implementation.
    ConfigureSystem(arch::Error),
    /// Legacy devices work with Event file descriptors and the creation can fail because
    /// of resource exhaustion.
    #[cfg(target_arch = "x86_64")]
    CreateLegacyDevice(device_manager::legacy::Error),
    /// Cannot read from an Event file descriptor.
    EventFd(io::Error),
    /// Polly error wrapper.
    EventManager(event_manager::Error),
    /// I8042 Error.
    #[cfg(target_arch = "x86_64")]
    I8042Error(devices::legacy::I8042DeviceError),
    /// Cannot access kernel file.
    KernelFile(io::Error),
    /// Cannot open /dev/kvm. Either the host does not have KVM or Firecracker does not have
    /// permission to open the file descriptor.
    KvmContext(vstate::Error),
    #[cfg(target_arch = "x86_64")]
    /// Cannot add devices to the Legacy I/O Bus.
    LegacyIOBus(device_manager::legacy::Error),
    /// Cannot load command line.
    LoadCommandline(kernel::cmdline::Error),
    /// Cannot add a device to the MMIO Bus.
    RegisterMMIODevice(device_manager::mmio::Error),
    /// Write to the serial console failed.
    Serial(io::Error),
    #[cfg(any(target_arch = "aarch64", target_arch = "riscv64"))]
    /// Cannot generate or write FDT
    SetupFDT(devices::fdt::Error),
    /// Cannot create Timer file descriptor.
    TimerFd(io::Error),
    /// Vcpu error.
    Vcpu(vstate::Error),
    /// Cannot send event to vCPU.
    VcpuEvent(vstate::Error),
    /// Cannot create a vCPU handle.
    VcpuHandle(vstate::Error),
    /// vCPU resume failed.
    VcpuResume,
    /// A live pause/resume failed; the VMM must be terminated.
    VcpuControl(String),
    /// Cannot spawn a new Vcpu thread.
    VcpuSpawn(std::io::Error),
    /// Vm error.
    Vm(vstate::Error),
    /// Error thrown by observer object on Vmm initialization.
    VmmObserverInit(utils::errno::Error),
    /// Error thrown by observer object on Vmm teardown.
    VmmObserverTeardown(utils::errno::Error),
}

impl Display for Error {
    fn fmt(&self, f: &mut Formatter) -> std::fmt::Result {
        use self::Error::*;

        match self {
            ConfigureSystem(e) => write!(f, "System configuration error: {e:?}"),
            #[cfg(target_arch = "x86_64")]
            CreateLegacyDevice(e) => write!(f, "Error creating legacy device: {e:?}"),
            EventFd(e) => write!(f, "Event fd error: {e}"),
            EventManager(e) => write!(f, "Event manager error: {e:?}"),
            #[cfg(target_arch = "x86_64")]
            I8042Error(e) => write!(f, "I8042 error: {e}"),
            KernelFile(e) => write!(f, "Cannot access kernel file: {e}"),
            KvmContext(e) => write!(f, "Failed to validate KVM support: {e:?}"),
            #[cfg(target_arch = "x86_64")]
            LegacyIOBus(e) => write!(f, "Cannot add devices to the legacy I/O Bus. {e}"),
            LoadCommandline(e) => write!(f, "Cannot load command line: {e}"),
            RegisterMMIODevice(e) => write!(f, "Cannot add a device to the MMIO Bus. {e}"),
            Serial(e) => write!(f, "Error writing to the serial console: {e:?}"),
            #[cfg(any(target_arch = "aarch64", target_arch = "riscv64"))]
            SetupFDT(e) => write!(f, "Error generating or writing FDT: {e:?}"),
            TimerFd(e) => write!(f, "Error creating timer fd: {e}"),
            Vcpu(e) => write!(f, "Vcpu error: {e}"),
            VcpuEvent(e) => write!(f, "Cannot send event to vCPU. {e:?}"),
            VcpuHandle(e) => write!(f, "Cannot create a vCPU handle. {e}"),
            VcpuResume => write!(f, "vCPUs resume failed."),
            VcpuControl(e) => write!(f, "vCPU control failed: {e}"),
            VcpuSpawn(e) => write!(f, "Cannot spawn Vcpu thread: {e}"),
            Vm(e) => write!(f, "Vm error: {e}"),
            VmmObserverInit(e) => write!(
                f,
                "Error thrown by observer object on Vmm initialization: {e}"
            ),
            VmmObserverTeardown(e) => {
                write!(f, "Error thrown by observer object on Vmm teardown: {e}")
            }
        }
    }
}

/// Trait for objects that need custom initialization and teardown during the Vmm lifetime.
pub trait VmmEventsObserver {
    /// This function will be called during microVm boot.
    fn on_vmm_boot(&mut self) -> std::result::Result<(), utils::errno::Error> {
        Ok(())
    }
    /// This function will be called on microVm teardown.
    fn on_vmm_stop(&mut self) -> std::result::Result<(), utils::errno::Error> {
        Ok(())
    }
}

/// Shorthand result type for internal VMM commands.
pub type Result<T> = std::result::Result<T, Error>;

/// Contains the state and associated methods required for the Firecracker VMM.
pub struct Vmm {
    // Guest VM core resources.
    guest_memory: GuestMemoryMmap,
    arch_memory_info: ArchMemoryInfo,

    kernel_cmdline: KernelCmdline,

    vcpus_handles: Vec<VcpuHandle>,
    exit_evt: EventFd,
    vm: Vm,
    exit_observers: Vec<Arc<Mutex<dyn VmmExitObserver>>>,
    exit_code: Arc<AtomicI32>,
    paused: bool,
    control_failed: bool,
    #[cfg(any(all(target_os = "macos", target_arch = "aarch64"), all(target_os = "linux", target_arch = "x86_64")))]
    snapshot_freeze_requested: bool,
    #[cfg(any(all(target_os = "macos", target_arch = "aarch64"), all(target_os = "linux", target_arch = "x86_64")))]
    snapshot_devices_frozen: bool,
    device_memory_gate: Arc<devices::virtio::memory_gate::MemoryGate>,
    #[cfg(target_os = "macos")]
    ram_unmapped: bool,
    #[cfg(target_os = "macos")]
    ram_fault_vcpus: Arc<devices::legacy::VcpuList>,

    // Guest VM devices.
    mmio_device_manager: MMIODeviceManager,
    #[cfg(target_arch = "x86_64")]
    pio_device_manager: PortIODeviceManager,
}

impl Vmm {
    /// Poll with the VMM lock released between calls and a caller-owned global
    /// deadline. CPU acknowledgement precedes worker shutdown; RAM gate closes
    /// only after every worker has returned ownership of its guest queues.
    #[cfg(any(all(target_os = "macos", target_arch = "aarch64"), all(target_os = "linux", target_arch = "x86_64")))]
    pub fn freeze_for_snapshot(&mut self) -> std::result::Result<bool, String> {
        if self.control_failed || self.device_memory_gate.has_prepare() {
            return Err("snapshot requires healthy mapped VM".into());
        }
        #[cfg(target_os = "macos")]
        if self.ram_unmapped {
            return Err("snapshot requires healthy mapped VM".into());
        }
        if self.snapshot_devices_frozen {
            return Ok(true);
        }
        if !self.snapshot_freeze_requested {
            if self.device_memory_gate.is_idle_closed() {
                return Err("freeze devices before closing RAM gate".into());
            }
            self.pause().map_err(|e| format!("pause for snapshot: {e:?}"))?;
            self.snapshot_freeze_requested = true;
        }
        if !self.mmio_device_manager.bus.freeze_snapshot_devices()? {
            return Ok(false);
        }
        if !self.device_memory_gate.try_close()? {
            return Ok(false);
        }
        #[cfg(all(target_os = "linux", target_arch = "x86_64"))]
        if !self.pio_device_manager.io_bus.freeze_snapshot_devices()? { return Ok(false); }
        self.snapshot_devices_frozen = true;
        Ok(true)
    }

    #[cfg(any(all(target_os = "macos", target_arch = "aarch64"), all(target_os = "linux", target_arch = "x86_64")))]
    pub fn capture_device_states(&self) -> std::result::Result<Vec<devices::snapshot::BusMappingSnapshot>, String> {
        self.require_ram_quiesced()?;
        if !self.snapshot_devices_frozen {
            return Err("device capture requires complete snapshot freeze".into());
        }
        self.mmio_device_manager.bus.capture_snapshot_devices()
    }

    /// Retain real RAM ranges only while CPUs and device users are quiescent.
    #[cfg(target_os = "macos")]
    pub fn experimental_ram_blocks(&self, chunk: usize) -> std::result::Result<Vec<ram::RamBlock>, String> {
        self.require_ram_quiesced()?;
        ram::blocks(&self.guest_memory, chunk)
    }

    #[cfg(any(all(target_os = "macos", target_arch = "aarch64"), all(target_os = "linux", target_arch = "x86_64")))]
    fn require_ram_quiesced(&self) -> std::result::Result<(), String> {
        if !self.paused || !self.device_memory_gate.is_idle_closed() || self.control_failed {
            return Err("RAM block access requires a healthy quiescent VM".into());
        }
        #[cfg(target_os = "macos")]
        if self.ram_unmapped { return Err("RAM is unmapped".into()); }
        if cfg!(any(feature = "gpu", feature = "snd", feature = "input", feature = "tee")) {
            return Err("RAM sampling unavailable with unguarded devices".into());
        }
        Ok(())
    }

    /// Capture CPU state on each owning thread. This does not capture devices
    /// and must never be published as a complete VM snapshot.
    #[cfg(any(all(target_os = "macos", target_arch = "aarch64"), all(target_os = "linux", target_arch = "x86_64")))]
    pub fn capture_cpu_states(&self) -> std::result::Result<Vec<CpuSnapshot>, String> {
        self.require_ram_quiesced()?;
        let deadline = Instant::now() + Duration::from_secs(3);
        self.vcpus_handles.iter().enumerate().map(|(id, cpu)| {
            let state = cpu.capture_state(deadline.saturating_duration_since(Instant::now()))?;
            state.validate(id as u8)?;
            Ok(state)
        }).collect()
    }

    /// Full RAM inventory while mappings are quiescent; DAX windows excluded.
    #[cfg(target_os = "macos")]
    pub fn experimental_ram_page_inventory(&self) -> std::result::Result<(u64, Vec<[u64; 4]>), String> {
        self.require_ram_quiesced()?;
        ram::page_inventory(&self.guest_memory)
    }

    pub fn is_paused(&self) -> bool { self.paused }

    /// Pause all vCPUs. Device workers and host I/O remain active.
    pub fn pause(&mut self) -> Result<()> {
        self.set_paused(true)
    }

    /// Resume all vCPUs. Guest clocks retain their existing wall-time semantics.
    pub fn resume(&mut self) -> Result<()> {
        if self.control_failed {
            return Err(Error::VcpuControl(
                "previous transition failed; terminate VMM".into(),
            ));
        }
        // ponytail: preserve wall-time clocks; freezing guest time requires the
        // matching HVF WFE offset support and KVM clock handling, not just pause.
        #[cfg(target_os = "macos")]
        if self.ram_unmapped && !self.control_failed {
            self.control_failed = true;
            for region in self
                .guest_memory
                .iter()
                .filter(|region| region.file_offset().is_some())
            {
                self.vm
                    .hvf_vm()
                    .map_memory(
                        region.as_ptr() as u64,
                        region.start_addr().raw_value(),
                        region.len(),
                    )
                    .map_err(|e| Error::VcpuControl(format!("restore RAM mapping: {e:?}")))?;
            }
            self.ram_unmapped = false;
            self.control_failed = false;
        }
        self.device_memory_gate.open();
        #[cfg(any(all(target_os = "macos", target_arch = "aarch64"), all(target_os = "linux", target_arch = "x86_64")))]
        if self.snapshot_freeze_requested {
            // A failed thaw is a partial transition. Keep CPU parked and
            // poison control rather than running it against missing workers.
            if let Err(error) = self.mmio_device_manager.bus.thaw_snapshot_devices() {
                self.control_failed = true;
                return Err(Error::VcpuControl(format!("snapshot thaw failed: {error}")));
            }
            #[cfg(all(target_os = "linux", target_arch = "x86_64"))]
            self.pio_device_manager.io_bus.thaw_snapshot_devices().map_err(Error::VcpuControl)?;
            self.snapshot_devices_frozen = false;
            self.snapshot_freeze_requested = false;
        }
        self.set_paused(false)
    }

    pub fn device_memory_gate(&self) -> Arc<devices::virtio::memory_gate::MemoryGate> {
        self.device_memory_gate.clone()
    }

    /// Advisory residency of owned file-backed RAM ranges, including anonymous
    /// replacements installed by the experimental pager. This does not pause CPUs.
    #[cfg(target_os = "macos")]
    pub fn experimental_ram_residency(&self) -> Option<u64> {
        ram::residency(&self.guest_memory)
    }

    /// Install an experimental RAM fault resolver only within a quiescent epoch.
    /// The resolver owns address validation; registration does not change mappings.
    #[cfg(target_os = "macos")]
    pub fn install_memory_fault_handler(&mut self, handler: Arc<hvf::MemoryFaultHandler>) -> Result<()> {
        if !self.paused || !self.device_memory_gate.is_idle_closed() || self.control_failed {
            return Err(Error::VcpuControl("RAM fault registration requires paused CPUs and drained devices".into()));
        }
        self.ram_fault_vcpus.set_memory_fault_handler(handler).map_err(Error::VcpuControl)
    }

    pub fn fail_control(&mut self) {
        self.control_failed = true;
    }

    /// Pause and flush/reclaim file-backed RAM. Host device mappings stay valid.
    pub fn offload_ram(&mut self) -> Result<ram::RamReclaim> {
        ram::check_reclaim(&self.guest_memory).map_err(Error::VcpuControl)?;
        if self.device_memory_gate.has_prepare() {
            return Err(Error::VcpuControl("whole-VM offload is incompatible with experimental RAM preparation".into()));
        }
        if cfg!(any(
            feature = "gpu",
            feature = "snd",
            feature = "input",
            feature = "tee"
        )) {
            return Err(Error::VcpuControl(
                "offload is unavailable with unguarded GPU/audio/input/TEE devices".into(),
            ));
        }
        if !self.device_memory_gate.is_idle_closed() {
            return Err(Error::VcpuControl(
                "device RAM access must be quiesced before offload".into(),
            ));
        }
        if !self
            .guest_memory
            .iter()
            .any(|region| region.file_offset().is_some())
        {
            return Err(Error::VcpuControl("VM has no file-backed RAM".into()));
        }
        self.pause()?;
        let before = ram::residency(&self.guest_memory);
        self.control_failed = true;
        #[cfg(target_os = "macos")]
        if !self.ram_unmapped {
            // HVF must release its GPA mappings before host pages can be reclaimed.
            for region in self
                .guest_memory
                .iter()
                .filter(|region| region.file_offset().is_some())
            {
                self.vm
                    .hvf_vm()
                    .unmap_memory(region.start_addr().raw_value(), region.len())
                    .map_err(|e| Error::VcpuControl(format!("offload RAM mapping: {e:?}")))?;
            }
            self.ram_unmapped = true;
        }
        let backed_bytes = ram::reclaim(&self.guest_memory).map_err(Error::VcpuControl)?;
        let after = ram::residency(&self.guest_memory);
        self.control_failed = false;
        Ok(ram::RamReclaim {
            backed_bytes,
            resident_before_bytes: before,
            resident_after_bytes: after,
        })
    }

    fn set_paused(&mut self, paused: bool) -> Result<()> {
        if self.control_failed {
            return Err(Error::VcpuControl(
                "previous transition failed; terminate VMM".into(),
            ));
        }
        if self.paused == paused {
            return Ok(());
        }
        // A partial transition is not safe to retry: late acknowledgements could
        // otherwise be mistaken for the next request's response.
        self.control_failed = true;
        for handle in &self.vcpus_handles {
            let event = if paused {
                VcpuEvent::Pause
            } else {
                VcpuEvent::Resume
            };
            handle.send_event(event).map_err(Error::VcpuEvent)?;
        }
        let deadline = Instant::now() + Duration::from_secs(3);
        let expected = if paused {
            VcpuResponse::Paused
        } else {
            VcpuResponse::Resumed
        };
        for handle in &self.vcpus_handles {
            match handle
                .response_receiver()
                .recv_timeout(deadline.saturating_duration_since(Instant::now()))
            {
                Ok(response) if response == expected => (),
                response => {
                    return Err(Error::VcpuControl(format!(
                        "unexpected response: {response:?}"
                    )));
                }
            }
        }
        self.paused = paused;
        self.control_failed = false;
        Ok(())
    }

    /// Gets the the specified bus device.
    pub fn get_bus_device(
        &self,
        device_type: DeviceType,
        device_id: &str,
    ) -> Option<&Mutex<dyn BusDevice>> {
        self.mmio_device_manager.get_device(device_type, device_id)
    }

    /// Starts the microVM vcpus.
    pub fn start_vcpus(&mut self, mut vcpus: Vec<Vcpu>) -> Result<()> {
        let vcpu_count = vcpus.len();

        Vcpu::register_kick_signal_handler();

        self.vcpus_handles.reserve(vcpu_count);

        for mut vcpu in vcpus.drain(..) {
            vcpu.set_mmio_bus(self.mmio_device_manager.bus.clone());

            self.vcpus_handles
                .push(vcpu.start_threaded().map_err(Error::VcpuHandle)?);
        }

        // The vcpus start off in the `Paused` state, let them run.
        #[cfg(any(all(target_os = "macos", target_arch = "aarch64"), all(target_os = "linux", target_arch = "x86_64")))]
        if self.snapshot_devices_frozen {
            let deadline = Instant::now() + Duration::from_secs(3);
            for handle in &self.vcpus_handles {
                match handle.response_receiver().recv_timeout(deadline.saturating_duration_since(Instant::now())) {
                    Ok(VcpuResponse::Paused) => (),
                    response => return Err(Error::VcpuControl(format!("restored CPU not parked: {response:?}"))),
                }
            }
            self.paused = true;
            return Ok(());
        }
        self.resume_vcpus()?;

        Ok(())
    }

    /// Sends a resume command to the vcpus.
    #[cfg(target_os = "linux")]
    pub fn resume_vcpus(&mut self) -> Result<()> {
        for handle in self.vcpus_handles.iter() {
            handle
                .send_event(VcpuEvent::Resume)
                .map_err(Error::VcpuEvent)?;
        }
        for handle in self.vcpus_handles.iter() {
            match handle
                .response_receiver()
                .recv_timeout(Duration::from_millis(1000))
            {
                Ok(VcpuResponse::Resumed) => (),
                _ => return Err(Error::VcpuResume),
            }
        }
        Ok(())
    }

    #[cfg(target_os = "macos")]
    pub fn resume_vcpus(&mut self) -> Result<()> {
        Ok(())
    }

    /// Configures the system for boot.
    pub fn configure_system(
        &self,
        vcpus: &[Vcpu],
        _intc: &IrqChip,
        initrd: &Option<InitrdConfig>,
        _smbios_oem_strings: &Option<Vec<String>>,
    ) -> Result<()> {
        #[cfg(target_arch = "x86_64")]
        {
            let cmdline_len = if cfg!(feature = "tee") {
                arch::x86_64::layout::CMDLINE_SEV_SIZE
            } else {
                self.kernel_cmdline.len() + 1
            };

            arch::x86_64::configure_system(
                &self.guest_memory,
                &self.arch_memory_info,
                vm_memory::GuestAddress(arch::x86_64::layout::CMDLINE_START),
                cmdline_len,
                initrd,
                vcpus.len() as u8,
            )
            .map_err(Error::ConfigureSystem)?;
        }

        #[cfg(target_arch = "aarch64")]
        {
            let vcpu_mpidr = vcpus.iter().map(|cpu| cpu.get_mpidr()).collect();
            fdt::create_fdt(
                &self.guest_memory,
                &self.arch_memory_info,
                vcpu_mpidr,
                self.kernel_cmdline.as_str(),
                self.mmio_device_manager.get_device_info(),
                _intc,
                initrd,
            )
            .map_err(Error::SetupFDT)?;
        }

        #[cfg(target_arch = "aarch64")]
        {
            arch::aarch64::configure_system(
                &self.guest_memory,
                &self.arch_memory_info,
                _smbios_oem_strings,
            )
            .map_err(Error::ConfigureSystem)?;
        }

        #[cfg(target_arch = "riscv64")]
        {
            fdt::create_fdt(
                &self.guest_memory,
                &self.arch_memory_info,
                vcpus.len() as u32,
                self.kernel_cmdline.as_str(),
                self.mmio_device_manager.get_device_info(),
                _intc,
                initrd,
            )
            .map_err(Error::SetupFDT)?;

            arch::riscv64::configure_system(&self.guest_memory, _smbios_oem_strings)
                .map_err(Error::ConfigureSystem)?;
        }

        Ok(())
    }

    /// Returns a reference to the inner `GuestMemoryMmap` object if present, or `None` otherwise.
    pub fn guest_memory(&self) -> &GuestMemoryMmap {
        &self.guest_memory
    }

    /// Injects CTRL+ALT+DEL keystroke combo in the i8042 device.
    #[cfg(target_arch = "x86_64")]
    pub fn send_ctrl_alt_del(&mut self) -> Result<()> {
        self.pio_device_manager
            .i8042
            .lock()
            .expect("i8042 lock was poisoned")
            .trigger_ctrl_alt_del()
            .map_err(Error::I8042Error)
    }

    /// Waits for all vCPUs to exit and terminates the Firecracker process.
    pub fn stop(&mut self, exit_code: i32) {
        info!("Vmm is stopping.");

        for observer in &self.exit_observers {
            observer
                .lock()
                .expect("Poisoned mutex for exit observer")
                .on_vmm_exit();
        }

        // Exit from Firecracker using the provided exit code. Safe because we're terminating
        // the process anyway.
        unsafe {
            libc::_exit(exit_code);
        }
    }

    /// Returns a reference to the inner KVM Vm object.
    pub fn kvm_vm(&self) -> &Vm {
        &self.vm
    }

    #[cfg(target_os = "macos")]
    pub fn add_mapping(
        &self,
        reply_sender: Sender<bool>,
        host_addr: u64,
        guest_addr: u64,
        len: u64,
    ) {
        self.vm
            .add_mapping(reply_sender, host_addr, guest_addr, len);
    }

    #[cfg(target_os = "macos")]
    pub fn remove_mapping(&self, reply_sender: Sender<bool>, guest_addr: u64, len: u64) {
        self.vm.remove_mapping(reply_sender, guest_addr, len);
    }
}

impl Subscriber for Vmm {
    /// Handle a read event (EPOLLIN).
    fn process(&mut self, event: &EpollEvent, _: &mut EventManager) {
        let source = event.fd();
        let event_set = event.event_set();

        if source == self.exit_evt.as_raw_fd() && event_set == EventSet::IN {
            let _ = self.exit_evt.read();
            // Query each vcpu for the exit_code.
            // The exit code set up by the guest takes preference over the one reported
            // by either a vcpu or the i8042 controller. An unexplained successful
            // VM shutdown is a bootstrap failure, never a successful workload.
            let vcpu_exit_code = self
                .vcpus_handles
                .iter()
                .find_map(|handle| match handle.response_receiver().try_recv() {
                    Ok(VcpuResponse::Exited(exit_code)) => Some(exit_code),
                    _ => None,
                })
                .unwrap_or(FC_EXIT_CODE_OK);
            let vmm_exit_code = self.exit_code.load(Ordering::SeqCst);
            let exit_code = shutdown_exit_code(vmm_exit_code, vcpu_exit_code);
            self.stop(exit_code);
        } else {
            error!("Spurious EventManager event for handler: Vmm");
        }
    }

    fn interest_list(&self) -> Vec<EpollEvent> {
        vec![EpollEvent::new(
            EventSet::IN,
            self.exit_evt.as_raw_fd() as u64,
        )]
    }
}

// Guest status wins; a shutdown without workload status must never report success.
fn shutdown_exit_code(guest: i32, vcpu: u8) -> i32 {
    if guest != i32::MAX {
        guest
    } else if vcpu == FC_EXIT_CODE_OK {
        125
    } else {
        vcpu as i32
    }
}

#[cfg(test)]
mod guest_exit_tests {
    #[test]
    fn shutdown_requires_workload_status_to_report_success() {
        assert_eq!(super::shutdown_exit_code(0, 1), 0);
        assert_eq!(super::shutdown_exit_code(7, 0), 7);
        assert_eq!(super::shutdown_exit_code(i32::MAX, 0), 125);
        assert_eq!(super::shutdown_exit_code(i32::MAX, 1), 1);
    }
}
